import asyncio

import pytest

from tenacity import retry, stop_after_attempt


@pytest.mark.parametrize("is_async", [False, True])
@pytest.mark.parametrize("succeed", [False, True])
def test_retry_statistics_shared_with_invocation(is_async, succeed):
    attempts = []

    def body():
        assert wrapped.retry.statistics is wrapped.statistics
        attempt = wrapped.retry.statistics["attempt_number"]
        attempts.append(attempt)
        if not succeed or attempt < 3:
            raise ValueError("retry me")
        return attempt

    if is_async:
        async def target():
            return body()
    else:
        target = body

    wrapped = retry(stop=stop_after_attempt(3), reraise=True)(target)
    assert wrapped.retry.statistics == {}
    previous = None
    for _ in range(2):
        if succeed:
            result = asyncio.run(wrapped()) if is_async else wrapped()
            assert result == 3
        else:
            with pytest.raises(ValueError, match="retry me"):
                asyncio.run(wrapped()) if is_async else wrapped()
        assert wrapped.retry.statistics is wrapped.statistics
        assert wrapped.retry.statistics["attempt_number"] == 3
        assert "start_time" in wrapped.retry.statistics
        assert wrapped.retry.statistics is not previous
        previous = wrapped.retry.statistics
    assert attempts == [1, 2, 3, 1, 2, 3]
EOF
python -m pytest -q tests/test_retry_statistics.py
